from collections import OrderedDict
from math import isqrt


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, capacity_bytes)
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost_probation = OrderedDict()
        self.ghost_protected = OrderedDict()
        self.ghost_limit = 4096
        self.protected_target = self.capacity_bytes // 2
        self.used_bytes = 0
        self.protected_bytes = 0
        self.frequency = {}
        self.frequency_limit = 8192
        self.tick = 0
        self.decay_period = 4096

    def _touch_frequency(self, key):
        self.tick += 1
        if self.tick % self.decay_period == 0:
            for old_key, count in tuple(self.frequency.items()):
                count >>= 1
                if count:
                    self.frequency[old_key] = count
                else:
                    del self.frequency[old_key]
        if key in self.frequency:
            self.frequency[key] = min(255, self.frequency[key] + 1)
            return
        if len(self.frequency) >= self.frequency_limit:
            weakest = min(self.frequency.values())
            for old_key in tuple(self.frequency):
                if self.frequency[old_key] == weakest:
                    del self.frequency[old_key]
                    if len(self.frequency) < self.frequency_limit:
                        break
        self.frequency[key] = 1

    def _remember(self, ghost, key):
        ghost.pop(key, None)
        ghost[key] = None
        while len(ghost) > self.ghost_limit:
            ghost.popitem(last=False)

    def _forget_ghost(self, key):
        self.ghost_probation.pop(key, None)
        self.ghost_protected.pop(key, None)

    def _rebalance(self):
        while self.protected and self.protected_bytes > self.protected_target:
            old_key, old_size = self.protected.popitem(last=False)
            self.protected_bytes -= old_size
            self.probation[old_key] = old_size

    def _evict_one(self):
        if self.probation:
            old_key, old_size = self.probation.popitem(last=False)
            self._remember(self.ghost_probation, old_key)
        elif self.protected:
            old_key, old_size = self.protected.popitem(last=False)
            self.protected_bytes -= old_size
            self._remember(self.ghost_protected, old_key)
        else:
            return None
        self.used_bytes -= old_size
        return old_key

    def _victim_plan(self, required_bytes):
        plan = []
        remaining = required_bytes
        for old_key, old_size in self.probation.items():
            if remaining <= 0:
                break
            plan.append((old_key, old_size))
            remaining -= old_size
        if remaining > 0:
            for old_key, old_size in self.protected.items():
                if remaining <= 0:
                    break
                plan.append((old_key, old_size))
                remaining -= old_size
        return plan

    def _should_admit(self, key, size, plan):
        candidate_frequency = self.frequency.get(key, 1)
        candidate_weight = max(1, isqrt(size))
        for old_key, old_size in plan:
            victim_frequency = self.frequency.get(old_key, 1)
            victim_weight = max(1, isqrt(old_size))
            if candidate_frequency * victim_weight < victim_frequency * candidate_weight:
                return False
        return True

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.protected:
            stored_size = self.protected.pop(key)
            self.protected[key] = stored_size
            self._touch_frequency(key)
            return []

        if key in self.probation:
            stored_size = self.probation.pop(key)
            self.protected[key] = stored_size
            self.protected_bytes += stored_size
            self._touch_frequency(key)
            self._rebalance()
            return []

        self._touch_frequency(key)
        if size <= 0 or size > self.capacity_bytes or self.capacity_bytes == 0:
            return []

        if key in self.ghost_probation:
            step = max(1, self.capacity_bytes // 16)
            self.protected_target = min(
                self.capacity_bytes,
                self.protected_target + max(step, min(size, self.capacity_bytes)),
            )
        elif key in self.ghost_protected:
            step = max(1, self.capacity_bytes // 16)
            self.protected_target = max(
                0,
                self.protected_target - max(step, min(size, self.capacity_bytes)),
            )
        self._forget_ghost(key)

        required_bytes = max(0, self.used_bytes + size - self.capacity_bytes)
        plan = self._victim_plan(required_bytes)
        if not self._should_admit(key, size, plan):
            return []

        evicted = []
        while self.used_bytes + size > self.capacity_bytes:
            old_key = self._evict_one()
            if old_key is None:
                break
            evicted.append(old_key)

        self.probation[key] = size
        self.used_bytes += size
        self._rebalance()
        return evicted
